// Tiny pictures for the tests: a PNG made here, and a 4×3 JPEG.
import { deflateSync, crc32 } from 'node:zlib';

// A w×h PNG: every pixel [r, g, b, a], or the RGBA pixels given.
export function png(w, h, fill) {
  const raw = Buffer.alloc((w * 4 + 1) * h);
  for (let y = 0; y < h; y++) {
    if (fill.length === w * h * 4) raw.set(fill.subarray(y * w * 4, (y + 1) * w * 4), y * (w * 4 + 1) + 1);
    else for (let x = 0; x < w; x++) raw.set(fill, y * (w * 4 + 1) + 1 + x * 4);
  }
  const chunk = (type, data) => {
    const len = Buffer.alloc(4); len.writeUInt32BE(data.length);
    const td = Buffer.concat([Buffer.from(type), data]);
    const crc = Buffer.alloc(4); crc.writeUInt32BE(crc32(td));
    return Buffer.concat([len, td, crc]);
  };
  const ihdr = Buffer.alloc(13);
  ihdr.writeUInt32BE(w, 0); ihdr.writeUInt32BE(h, 4); ihdr.set([8, 6, 0, 0, 0], 8);   // 8-bit RGBA
  return new Uint8Array(Buffer.concat([
    Buffer.from([137, 80, 78, 71, 13, 10, 26, 10]), chunk('IHDR', ihdr), chunk('IDAT', deflateSync(raw)), chunk('IEND', Buffer.alloc(0)),
  ]));
}

export const jpeg = new Uint8Array(Buffer.from('', 'base64'));   // 4×3, all red
